<?php

declare(strict_types=1);
if (basename((string)($_SERVER['SCRIPT_FILENAME'] ?? '')) === basename(__FILE__)) { http_response_code(403); exit; }

function v50_has_hypothesis(string $classId,string $studentKey,int $lessonNo): bool
{
    foreach(v50_student_events($classId,$studentKey,$lessonNo) as $row)if((string)($row['kind']??'')==='hypothesis')return true;return false;
}
function v50_last_event_of_kind(string $classId,string $studentKey,int $lessonNo,string $kind): ?array
{
    $last=null;foreach(v50_student_events($classId,$studentKey,$lessonNo) as $row)if((string)($row['kind']??'')===$kind)$last=$row;return is_array($last)?$last:null;
}
function v50_dim_label(string $dim): string
{
    return match($dim){'principle'=>tr('Znám princip'),'recognition'=>tr('Poznám problém'),'diagnosis'=>tr('Umím diagnostikovat'),'repair'=>tr('Umím opravit'),'explain'=>tr('Umím vysvětlit'),'transfer'=>tr('Umím použít jinde'),default=>$dim};
}
function v50_topology_svg(array $spec): void
{
    $top=(array)($spec['topology']??[]);$nodes=(array)($top['nodes']??[]);$edges=(array)($top['edges']??[]);$path=(array)($top['packet_path']??[]);
    ?><div class="v50-topology" data-v50-topology data-packet-path="<?=e(implode(',',$path))?>">
      <div class="v50-layer-switch" role="group" aria-label="<?=e(tr('Vrstva diagramu'))?>"><button type="button" data-layer="all" class="active"><?=e(tr('Vše'))?></button><button type="button" data-layer="L2">L2</button><button type="button" data-layer="L3">L3</button><button type="button" data-layer="L4">L4</button><button type="button" data-layer="L7">L7</button><button type="button" data-layer="OS">OS</button></div>
      <svg viewBox="0 0 100 70" role="img" aria-label="<?=e(tr('Interaktivní topologie labu'))?>">
        <defs><marker id="v50-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z"/></marker><filter id="v50-glow"><feGaussianBlur stdDeviation="1.2" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>
        <?php foreach($edges as $i=>$edge): $a=null;$b=null;foreach($nodes as $n){if(($n['id']??'')===($edge['from']??''))$a=$n;if(($n['id']??'')===($edge['to']??''))$b=$n;}if(!$a||!$b)continue; ?><g class="v50-edge" data-layer="<?=e((string)($edge['layer']??''))?>"><line x1="<?=e((string)$a['x'])?>" y1="<?=e((string)$a['y'])?>" x2="<?=e((string)$b['x'])?>" y2="<?=e((string)$b['y'])?>" marker-end="url(#v50-arrow)"/><text x="<?=e((string)(($a['x']+$b['x'])/2))?>" y="<?=e((string)(($a['y']+$b['y'])/2-2))?>"><?=e((string)($edge['label']??''))?></text></g><?php endforeach; ?>
        <?php foreach($nodes as $node): ?><g class="v50-node" tabindex="0" role="button" data-node="<?=e((string)$node['id'])?>" data-layer="<?=e((string)$node['layer'])?>" data-label="<?=e((string)$node['label'])?>" data-meta="<?=e((string)$node['meta'])?>" transform="translate(<?=e((string)$node['x'])?> <?=e((string)$node['y'])?>)"><circle r="6"/><text y=".8" text-anchor="middle" class="v50-node-mark"><?=e(strtoupper(substr((string)$node['kind'],0,1)))?></text><text y="10" text-anchor="middle" class="v50-node-label"><?=e((string)$node['label'])?></text></g><?php endforeach; ?>
        <circle class="v50-packet" r="1.8" cx="8" cy="50" aria-hidden="true"/>
      </svg>
      <div class="v50-topology-tools"><button type="button" class="btn secondary small" data-packet-play><?=e(tr('▶ Přehrát packet path'))?></button><div class="v50-inspector" data-v50-inspector><strong><?=e(tr('Vyber uzel'))?></strong><span><?=e(tr('Kliknutím zjistíš roli a adresu prvku.'))?></span></div></div>
    </div><?php
}

function v50_render_student_hands_on_page(string $classId,array $lesson,array $module,string $flash=''): void
{
