      <header class="v50-hero"><div><div class="eyebrow">v50 · Hands-on Learning Runtime</div><h1><?=edu_cs((string)$spec['lesson_title'])?></h1><p><?=edu_cs((string)$spec['mission'])?></p><div class="v50-chip-row"><span><?=edu_cs((string)$spec['family_label'])?></span><span><?=edu_cs((string)$spec['layer'])?></span><span><?=e(v50_runtime_mode()==='oci'?tr('Real OCI Linux'):tr('Stateful simulator'))?></span><?php if(!empty($spec['boss_fight'])):?><strong>Boss Fight</strong><?php endif;?></div></div><div class="v50-hero-actions"><a class="btn primary" href="<?=e(v69_task_url('lab',['lesson'=>(string)$lessonNo],module_url('hands_on',['lesson'=>$lessonNo])))?>">One Task Mode →</a><a class="btn secondary" href="<?=e(module_url('visual_lab',['lesson'=>$lessonNo]))?>">Visual Lab</a><a class="btn secondary" href="?view=skill_passport">Skill Passport</a></div></header>
      <?php if($flash!==''):?><div class="notice"><?=e($flash)?></div><?php endif;?>
      <?php if($stop):?><section class="v50-stop-card"><div><span><?=e(tr('✓ Dostatek kvalitní evidence'))?></span><h2><?=e(tr('Pro dnešek stačí.'))?></h2><p><?=e(tr('Diagnostiku, opravu, vysvětlení i transfer už máš doložené. Další opakování stejného typu by teď mělo menší přínos.'))?></p></div><a class="btn primary" href="?view=growth"><?=e(tr('Chci se rozvíjet dál'))?></a></section><?php endif;?>
      <div class="v50-main-grid">
