        <aside class="v50-card v50-passport-mini"><div class="v50-section-head"><div><span>Skill Passport</span><h2><?=e(tr('Co už umíš prokázat'))?></h2></div></div><?php foreach($passport as $dim=>$pct):?><div class="v50-dim"><div><span><?=e(v50_dim_label($dim))?></span><strong><?=(int)$pct?>%</strong></div><i><b style="width:<?=(int)$pct?>%"></b></i></div><?php endforeach;?><a href="?view=skill_passport"><?=e(tr('Otevřít celý Passport →'))?></a></aside>
      </div>

      <section class="v50-card"><div class="v50-section-head"><div><span><?=e(tr('02 · Předpověz'))?></span><h2><?=e(tr('Hypotéza před terminálem'))?></h2></div><small><?=e(tr('Terminál se odemyká až po commitnutí modelu.'))?></small></div><?php if(!$hasHyp):?><form method="post" class="v50-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="v50_hypothesis"><input type="hidden" name="lesson_number" value="<?=$lessonNo?>"><label><?=edu_cs((string)$spec['hypothesis_prompt'])?><textarea name="hypothesis" rows="3" required minlength="18" maxlength="1400" placeholder="<?=e(tr('Myslím, že… Vyvrátil by to výsledek…'))?>"></textarea></label><button class="btn primary"><?=e(tr('Commitnout hypotézu a odemknout lab'))?></button></form><?php else:?><div class="v50-complete-line"><span>✓</span><div><strong><?=e(tr('Hypotéza je commitnutá'))?></strong><p><?=e(tr('Teď hledej důkaz, který ji může potvrdit nebo vyvrátit.'))?></p></div></div><?php endif;?></section>

      <section class="v50-card <?=!$hasHyp?'v50-locked':''?>"><div class="v50-section-head"><div><span><?=e(tr('03 · Měř'))?></span><h2><?=e(tr('Terminál + evidence'))?></h2></div><small><?=e(v50_runtime_mode()==='oci'?tr('Ephemeral rootless OCI sandbox'):tr('Bezpečný stateful simulator'))?></small></div>
        <?php if(!$hasHyp):?><div class="v50-lock"><strong><?=e(tr('Nejdřív hypotéza.'))?></strong><span><?=e(tr('Bez předpovědi se z terminálu snadno stane náhodné zkoušení příkazů.'))?></span></div><?php else:?><div class="v50-terminal" data-v50-terminal><div class="v50-terminal-bar"><i></i><i></i><i></i><span>student@educanet-lab:~</span></div><pre data-terminal-output><?=e((string)($lastCmd['output']??tr('Terminál je připraven. Zvol nejmenší test, který něco rozliší.')))?></pre><form method="post" class="v50-command-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="v50_command"><input type="hidden" name="lesson_number" value="<?=$lessonNo?>"><label><span>$</span><input name="command" required autocomplete="off" spellcheck="false" list="v50-command-list" placeholder="<?=e(tr('napiš bezpečný diagnostický příkaz'))?>"></label><datalist id="v50-command-list"><?php foreach($spec['allowed_commands'] as $cmd):?><option value="<?=e((string)$cmd)?>"><?php endforeach;?></datalist><button class="btn primary"><?=e(tr('Spustit'))?></button></form></div><div class="v50-command-palette"><span><?=e(tr('Možné nástroje pro tento sandbox'))?></span><?php foreach(array_slice((array)$spec['allowed_commands'],0,8) as $cmd):?><button type="button" data-command-fill="<?=e((string)$cmd)?>"><code><?=e((string)$cmd)?></code></button><?php endforeach;?></div><?php endif;?>
      </section>

      <section class="v50-two-col">
        <article class="v50-card"><div class="v50-section-head"><div><span><?=e(tr('04 · Least help first'))?></span><h2><?=e(tr('Nápověda bez prozrazení'))?></h2></div></div><div class="v50-hints"><?php foreach($spec['hints'] as $hint):?><details><summary><b><?=e(tr('Úroveň {level}',['level'=>(int)$hint['level']]))?></b> <?=edu_cs((string)$hint['label'])?></summary><p><?=edu_cs((string)$hint['text'])?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="v50_hint"><input type="hidden" name="lesson_number" value="<?=$lessonNo?>"><input type="hidden" name="hint_level" value="<?=(int)$hint['level']?>"><button class="v50-text-button"><?=e(tr('Zaznamenat použití této nápovědy'))?></button></form></details><?php endforeach;?></div></article>
        <article class="v50-card"><div class="v50-section-head"><div><span><?=e(tr('05 · Ověř stav'))?></span><h2><?=e(tr('Ne „správný příkaz“, ale funkční systém'))?></h2></div></div><p><?=edu_cs((string)$spec['proof'])?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="v50_validate"><input type="hidden" name="lesson_number" value="<?=$lessonNo?>"><button class="btn primary"><?=e(tr('Ověřit výsledný stav'))?></button></form><?php if($lastValidation):?><div class="v50-validation <?=!empty($lastValidation['correct'])?'ok':'no'?>"><?=e(!empty($lastValidation['correct'])?tr('✓ Stav splňuje checkpoint.'):tr('Ještě ne. Získej další důkaz nebo oprav skutečnou příčinu.'))?></div><?php endif;?></article>
      </section>

      <section class="v50-two-col"><article class="v50-card"><div class="v50-section-head"><div><span><?=e(tr('06 · Vysvětli'))?></span><h2><?=e(tr('Root cause vlastními slovy'))?></h2></div></div><form method="post" class="v50-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="v50_explain"><input type="hidden" name="lesson_number" value="<?=$lessonNo?>"><textarea name="explanation" rows="4" minlength="28" required placeholder="<?=e(tr('Příčina byla… Důkazem je… Oprava funguje, protože…'))?>"></textarea><button class="btn secondary"><?=e(tr('Uložit vysvětlení'))?></button></form></article><article class="v50-card"><div class="v50-section-head"><div><span><?=e(tr('07 · Přenes'))?></span><h2><?=e(tr('Nový kontext'))?></h2></div></div><p><?=edu_cs((string)$spec['transfer'])?></p><form method="post" class="v50-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="v50_transfer"><input type="hidden" name="lesson_number" value="<?=$lessonNo?>"><textarea name="transfer" rows="4" minlength="28" required placeholder="<?=e(tr('Stejný princip by… Znovu bych ale ověřil…'))?>"></textarea><button class="btn secondary"><?=e(tr('Uložit transfer'))?></button></form></article></section>
