function v50_render_skill_passport(string $classId,array $module,string $flash=''): void
{
    $studentKey=adaptive_student_key($classId);$passport=v50_student_passport($classId,$studentKey);$capstones=v50_growth_capstones_for_student($classId,$studentKey);render_header(tr('Skill Passport'),$module);
