></article></section><section class="v50-card"><div class="v50-peer-notes"><?php foreach(array_reverse((array)$room['notes']) as $note):?><article><b><?=e((string)$note['type'])?></b><p><?=edu_cs((string)$note['text'])?></p><small><?=e((string)$note['created_at'])?></small></article><?php endforeach;?></div></section><?php endif;?></section><?php render_footer();
}

