function v50_render_teacher_lesson_card(string $classId,int $lessonNo): void
{
    if(!in_array($classId,['class_3a','class_4a'],true))return;
    $lesson=v42_find_lesson($classId,max(1,min(28,$lessonNo)));if(!$lesson)return;
    $spec=v50_lab_spec($classId,$lesson,'teacher-preview');
    ?><section class="teacher-panel v50-teacher-mission"><div class="teacher-panel-head"><div><span>v50 · Hands-on mise</span><h2><?=e((string)$spec['lesson_title'])?></h2><p><?=e((string)$spec['mission'])?></p></div><?php if(!empty($spec['boss_fight'])):?><b class="v50-boss-pill">Boss Fight</b><?php endif;?></div><div class="v50-teacher-mission-grid"><article><span>Hypotéza</span><p><?=e((string)$spec['hypothesis_prompt'])?></p></article><article><span>Minimální důkaz</span><p><?=e((string)$spec['proof'])?></p></article><article><span>Transfer</span><p><?=e((string)$spec['transfer'])?></p></article></div><div class="v50-chip-row"><span><?=e((string)$spec['family_label'])?></span><span><?=e((string)$spec['layer'])?></span><span><?=count((array)$spec['allowed_commands'])?> bezpečných nástrojů</span></div></section><?php
}
